INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000600', 'Petrofisika adalah ilmu yang mempelajari sifat fisik batuan dan fluida reservoir dengan tujuan utama...', 'Petrophysics is the study of the physical properties of reservoir rocks and fluids with the main purpose of...', 'option', 'PFC000000001', 'Inisialisasi', 'a:4:{i:0;s:22:"Mengatur jadwal ekspor";i:1;s:47:"Menghitung cadangan dan karakterisasi reservoir";i:2;s:25:"Merancang pompa permukaan";i:3;s:28:"Menentukan harga jual minyak";}', 'a:4:{i:0;s:25:"Managing export schedules";i:1;s:53:"Calculating reserves and characterizing the reservoir";i:2;s:23:"Designing surface pumps";i:3;s:36:"Determining the selling price of oil";}', '', 'Menghitung cadangan dan karakterisasi reservoir', 'Calculating reserves and characterizing the reservoir', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000601', 'Porositas batuan umumnya dinyatakan dalam satuan...', 'Rock porosity is generally expressed in units of...', 'option', 'PFC000000001', 'Inisialisasi', 'a:4:{i:0;s:18:"Fraksi atau persen";i:1;s:3:"psi";i:2;s:2:"mD";i:3;s:11:"Derajat API";}', 'a:4:{i:0;s:19:"Fraction or percent";i:1;s:3:"psi";i:2;s:2:"mD";i:3;s:11:"API degrees";}', '', 'Fraksi atau persen', 'Fraction or percent', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000602', 'Porositas 20% termasuk kategori kualitas...', 'A porosity of 20% falls into the quality category...', 'option', 'PFC000000001', 'Inisialisasi', 'a:4:{i:0;s:13:"Tidak terukur";i:1;s:5:"Buruk";i:2;s:11:"Baik (good)";i:3;s:12:"Sangat buruk";}', 'a:4:{i:0;s:12:"Unmeasurable";i:1;s:4:"Poor";i:2;s:4:"Good";i:3;s:9:"Very poor";}', '', 'Baik (good)', 'Good', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000603', 'Syarat utama agar batuan dapat disebut batuan reservoir adalah memiliki...', 'The main requirement for a rock to be called a reservoir rock is that it has...', 'option', 'PFC000000001', 'Inisialisasi', 'a:4:{i:0;s:22:"Warna terang dan keras";i:1;s:29:"Kandungan lempung yang tinggi";i:2;s:68:"Porositas untuk menyimpan dan permeabilitas untuk mengalirkan fluida";i:3;s:26:"Berat jenis di atas 3 g/cc";}', 'a:4:{i:0;s:27:"A bright color and hardness";i:1;s:19:"A high clay content";i:2;s:54:"Porosity to store fluids and permeability to flow them";i:3;s:31:"A specific gravity above 3 g/cc";}', '', 'Porositas untuk menyimpan dan permeabilitas untuk mengalirkan fluida', 'Porosity to store fluids and permeability to flow them', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000604', 'Porositas yang terbentuk selama proses pengendapan sedimen disebut porositas...', 'Porosity formed during the sediment deposition process is called...', 'option', 'PFC000000001', 'Inisialisasi', 'a:4:{i:0;s:8:"Sekunder";i:1;s:6:"Primer";i:2;s:7:"Fraktur";i:3;s:5:"Vuggy";}', 'a:4:{i:0;s:9:"Secondary";i:1;s:7:"Primary";i:2;s:8:"Fracture";i:3;s:5:"Vuggy";}', '', 'Primer', 'Primary', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000605', 'Satuan permeabilitas dalam sistem Darcy adalah...', 'The unit of permeability in the Darcy system is...', 'option', 'PFC000000001', 'Inisialisasi', 'a:4:{i:0;s:20:"Darcy atau miliDarcy";i:1;s:6:"Pascal";i:2;s:6:"Persen";i:3;s:7:"gram/cc";}', 'a:4:{i:0;s:19:"Darcy or milliDarcy";i:1;s:6:"Pascal";i:2;s:7:"Percent";i:3;s:7:"gram/cc";}', '', 'Darcy atau miliDarcy', 'Darcy or milliDarcy', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000606', 'Bagian reservoir yang produktif mengalirkan hidrokarbon disebut...', 'The productive part of a reservoir that flows hydrocarbons is called...', 'option', 'PFC000000001', 'Inisialisasi', 'a:4:{i:0;s:15:"Gross thickness";i:1;s:13:"Shale barrier";i:2;s:10:"Overburden";i:3;s:7:"Net pay";}', 'a:4:{i:0;s:15:"Gross thickness";i:1;s:13:"Shale barrier";i:2;s:10:"Overburden";i:3;s:7:"Net pay";}', '', 'Net pay', 'Net pay', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000607', 'Manakah yang termasuk komponen penyusun batuan reservoir?', 'Which of the following are components of a reservoir rock?', 'multi', 'PFC000000001', 'Inisialisasi', 'a:4:{i:0;s:19:"Pipa selubung sumur";i:1;s:19:"Fluida pengisi pori";i:2;s:14:"Matriks batuan";i:3;s:10:"Ruang pori";}', 'a:4:{i:0;s:11:"Well casing";i:1;s:23:"Fluid filling the pores";i:2;s:11:"Rock matrix";i:3;s:10:"Pore space";}', '', 'a:3:{i:0;s:14:"Matriks batuan";i:1;s:10:"Ruang pori";i:2;s:19:"Fluida pengisi pori";}', 'a:3:{i:0;s:11:"Rock matrix";i:1;s:10:"Pore space";i:2;s:23:"Fluid filling the pores";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000608', 'Urutkan proses pembentukan batuan sedimen dari awal sampai akhir.', 'Arrange the sedimentary rock formation process from beginning to end.', 'drag', 'PFC000000001', 'Inisialisasi', 'a:5:{i:0;s:19:"Pelapukan dan erosi";i:1;s:20:"Transportasi sedimen";i:2;s:11:"Pengendapan";i:3;s:22:"Kompaksi dan sementasi";i:4;s:12:"Metamorfisme";}', 'a:5:{i:0;s:22:"Weathering and erosion";i:1;s:18:"Sediment transport";i:2;s:10:"Deposition";i:3;s:26:"Compaction and cementation";i:4;s:12:"Metamorphism";}', '', 'a:4:{i:0;s:19:"Pelapukan dan erosi";i:1;s:20:"Transportasi sedimen";i:2;s:11:"Pengendapan";i:3;s:22:"Kompaksi dan sementasi";}', 'a:4:{i:0;s:22:"Weathering and erosion";i:1;s:18:"Sediment transport";i:2;s:10:"Deposition";i:3;s:26:"Compaction and cementation";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000609', 'Benarkah petrofisika hanya dibutuhkan pada fase produksi, tidak pada fase eksplorasi?', 'Is it true that petrophysics is only needed in the production phase, not in the exploration phase?', 'yesorno', 'PFC000000001', 'Inisialisasi', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000610', 'Sebuah core memiliki bulk volume 100 cm3 dan grain volume 75 cm3. Berapa porositas batuan tersebut?', 'A core has a bulk volume of 100 cm3 and a grain volume of 75 cm3. What is the porosity of the rock?', 'option', 'PFC000000001', 'Final Advanced', 'a:4:{i:0;s:3:"20%";i:1;s:3:"15%";i:2;s:3:"33%";i:3;s:3:"25%";}', 'a:4:{i:0;s:3:"20%";i:1;s:3:"15%";i:2;s:3:"33%";i:3;s:3:"25%";}', '', '25%', '25%', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000611', 'Batuan memiliki porositas total 30% dan saturasi air 40%. Berapa volume hidrokarbon per 1 m3 batuan?', 'A rock has a total porosity of 30% and a water saturation of 40%. What is the hydrocarbon volume per 1 m3 of rock?', 'option', 'PFC000000001', 'Final Advanced', 'a:4:{i:0;s:7:"0,30 m3";i:1;s:7:"0,40 m3";i:2;s:7:"0,18 m3";i:3;s:7:"0,12 m3";}', 'a:4:{i:0;s:7:"0.30 m3";i:1;s:7:"0.40 m3";i:2;s:7:"0.18 m3";i:3;s:7:"0.12 m3";}', '', '0,18 m3', '0.18 m3', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000612', 'Diketahui bulk density 2,35 g/cc, densitas matriks 2,65 g/cc, dan densitas fluida 1,00 g/cc. Berapa porositas berdasarkan persamaan densitas?', 'Given a bulk density of 2.35 g/cc, a matrix density of 2.65 g/cc, and a fluid density of 1.00 g/cc. What is the density-derived porosity?', 'option', 'PFC000000001', 'Final Advanced', 'a:4:{i:0;s:5:"18,2%";i:1;s:5:"11,3%";i:2;s:5:"30,0%";i:3;s:5:"25,0%";}', 'a:4:{i:0;s:5:"18.2%";i:1;s:5:"11.3%";i:2;s:5:"30.0%";i:3;s:5:"25.0%";}', '', '18,2%', '18.2%', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000613', 'Pada batuan karbonat, porositas yang terbentuk dari lubang pelarutan berukuran besar disebut...', 'In carbonate rocks, porosity formed by large dissolution cavities is called...', 'option', 'PFC000000001', 'Final Advanced', 'a:4:{i:0;s:22:"Intergranular porosity";i:1;s:14:"Vuggy porosity";i:2;s:25:"Intercrystalline porosity";i:3;s:13:"Microporosity";}', 'a:4:{i:0;s:22:"Intergranular porosity";i:1;s:14:"Vuggy porosity";i:2;s:25:"Intercrystalline porosity";i:3;s:13:"Microporosity";}', '', 'Vuggy porosity', 'Vuggy porosity', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000614', 'Peningkatan intensitas sementasi pada batupasir umumnya menyebabkan...', 'Increasing cementation intensity in sandstone generally causes...', 'option', 'PFC000000001', 'Final Advanced', 'a:4:{i:0;s:35:"Porositas naik, permeabilitas turun";i:1;s:22:"Keduanya tidak berubah";i:2;s:35:"Porositas turun, permeabilitas naik";i:3;s:35:"Porositas dan permeabilitas menurun";}', 'a:4:{i:0;s:49:"Porosity to increase and permeability to decrease";i:1;s:17:"Neither to change";i:2;s:49:"Porosity to decrease and permeability to increase";i:3;s:42:"Both porosity and permeability to decrease";}', '', 'Porositas dan permeabilitas menurun', 'Both porosity and permeability to decrease', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000615', 'Rasio net-to-gross (NTG) digunakan untuk...', 'The net-to-gross (NTG) ratio is used to...', 'option', 'PFC000000001', 'Final Advanced', 'a:4:{i:0;s:27:"Menghitung laju injeksi air";i:1;s:61:"Memisahkan ketebalan produktif dari total ketebalan reservoir";i:2;s:28:"Menentukan jenis semen sumur";i:3;s:26:"Mengoreksi densitas fluida";}', 'a:4:{i:0;s:30:"Calculate water injection rate";i:1;s:60:"Separate productive thickness from total reservoir thickness";i:2;s:33:"Determine the type of well cement";i:3;s:21:"Correct fluid density";}', '', 'Memisahkan ketebalan produktif dari total ketebalan reservoir', 'Separate productive thickness from total reservoir thickness', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000616', 'Kehadiran lempung pada batupasir terutama menurunkan porositas efektif karena...', 'The presence of clay in sandstone mainly reduces effective porosity because...', 'option', 'PFC000000001', 'Final Advanced', 'a:4:{i:0;s:29:"Lempung menghilangkan rekahan";i:1;s:38:"Lempung menambah volume butiran kuarsa";i:2;s:50:"Lempung meningkatkan densitas matriks secara tetap";i:3;s:55:"Air terikat pada permukaan lempung menempati ruang pori";}', 'a:4:{i:0;s:22:"Clay removes fractures";i:1;s:29:"Clay adds quartz grain volume";i:2;s:39:"Clay increases matrix density uniformly";i:3;s:48:"Water bound to clay surfaces occupies pore space";}', '', 'Air terikat pada permukaan lempung menempati ruang pori', 'Water bound to clay surfaces occupies pore space', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000617', 'Tortuositas yang tinggi pada jalur aliran fluida akan...', 'High tortuosity in the fluid flow path will...', 'option', 'PFC000000001', 'Final Advanced', 'a:4:{i:0;s:26:"Meningkatkan permeabilitas";i:1;s:24:"Menurunkan permeabilitas";i:2;s:31:"Tidak memengaruhi permeabilitas";i:3;s:25:"Menaikkan porositas total";}', 'a:4:{i:0;s:21:"Increase permeability";i:1;s:21:"Decrease permeability";i:2;s:23:"Not affect permeability";i:3;s:23:"Increase total porosity";}', '', 'Menurunkan permeabilitas', 'Decrease permeability', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000618', 'Batuan dengan porositas 6% dan permeabilitas 0,05 mD paling tepat dikategorikan sebagai...', 'A rock with 6% porosity and 0.05 mD permeability is best categorized as...', 'option', 'PFC000000001', 'Final Advanced', 'a:4:{i:0;s:32:"Reservoir tight (kualitas buruk)";i:1;s:27:"Reservoir karbonat berongga";i:2;s:37:"Reservoir dengan permeabilitas tinggi";i:3;s:39:"Reservoir konvensional berkualitas baik";}', 'a:4:{i:0;s:32:"A tight (poor-quality) reservoir";i:1;s:27:"A vuggy carbonate reservoir";i:2;s:29:"A high-permeability reservoir";i:3;s:37:"A good-quality conventional reservoir";}', '', 'Reservoir tight (kualitas buruk)', 'A tight (poor-quality) reservoir', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000619', 'Porositas sekunder pada batuan karbonat umumnya terbentuk akibat...', 'Secondary porosity in carbonate rocks generally forms as a result of...', 'option', 'PFC000000001', 'Final Advanced', 'a:4:{i:0;s:34:"Pemadatan sedimen saat pengendapan";i:1;s:47:"Proses pelarutan (dissolution) dan dolomitisasi";i:2;s:29:"Pemilahan butir yang sempurna";i:3;s:41:"Pengangkatan batuan tanpa perubahan kimia";}', 'a:4:{i:0;s:37:"Sediment compaction during deposition";i:1;s:40:"Dissolution processes and dolomitization";i:2;s:21:"Perfect grain sorting";i:3;s:30:"Uplift without chemical change";}', '', 'Proses pelarutan (dissolution) dan dolomitisasi', 'Dissolution processes and dolomitization', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000620', 'Rekahan (fracture) pada reservoir karbonat umumnya memberikan kontribusi terbesar terhadap...', 'Fractures in a carbonate reservoir generally contribute most to...', 'option', 'PFC000000001', 'Final Advanced', 'a:4:{i:0;s:15:"Porositas total";i:1;s:21:"Permeabilitas efektif";i:2;s:16:"Densitas matriks";i:3;s:20:"Saturasi air terikat";}', 'a:4:{i:0;s:14:"Total porosity";i:1;s:22:"Effective permeability";i:2;s:14:"Matrix density";i:3;s:28:"Irreducible water saturation";}', '', 'Permeabilitas efektif', 'Effective permeability', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000621', 'Data tekanan reservoir paling andal digunakan untuk menentukan...', 'Reservoir pressure data are most reliably used to determine...', 'option', 'PFC000000001', 'Final Advanced', 'a:4:{i:0;s:25:"Kandungan mineral lempung";i:1;s:33:"Kontak fluida seperti GOC dan WOC";i:2;s:17:"Kadar air terikat";i:3;s:22:"Porositas total batuan";}', 'a:4:{i:0;s:20:"Clay mineral content";i:1;s:34:"Fluid contacts such as GOC and WOC";i:2;s:19:"Bound water content";i:3;s:19:"Total rock porosity";}', '', 'Kontak fluida seperti GOC dan WOC', 'Fluid contacts such as GOC and WOC', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000622', 'Manakah data yang diperlukan untuk perhitungan volumetrik cadangan hidrokarbon (OOIP)?', 'Which data are required for the volumetric calculation of hydrocarbon reserves (OOIP)?', 'multi', 'PFC000000001', 'Final Advanced', 'a:5:{i:0;s:30:"Faktor volumetrik formasi (Bo)";i:1;s:19:"Luas area (acreage)";i:2;s:17:"Ketebalan net pay";i:3;s:20:"Saturasi hidrokarbon";i:4;s:9:"Porositas";}', 'a:5:{i:0;s:28:"Formation volume factor (Bo)";i:1;s:22:"Areal extent (acreage)";i:2;s:17:"Net pay thickness";i:3;s:22:"Hydrocarbon saturation";i:4;s:8:"Porosity";}', '', 'a:5:{i:0;s:19:"Luas area (acreage)";i:1;s:17:"Ketebalan net pay";i:2;s:9:"Porositas";i:3;s:20:"Saturasi hidrokarbon";i:4;s:30:"Faktor volumetrik formasi (Bo)";}', 'a:5:{i:0;s:22:"Areal extent (acreage)";i:1;s:17:"Net pay thickness";i:2;s:8:"Porosity";i:3;s:22:"Hydrocarbon saturation";i:4;s:28:"Formation volume factor (Bo)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000623', 'Manakah pernyataan yang benar tentang porositas efektif?', 'Which statements about effective porosity are correct?', 'multi', 'PFC000000001', 'Final Advanced', 'a:4:{i:0;s:41:"Hanya mencakup pori yang saling terhubung";i:1;s:39:"Selalu lebih besar dari porositas total";i:2;s:40:"Dipengaruhi oleh sementasi dan pemadatan";i:3;s:50:"Menjadi acuan utama perhitungan volume hidrokarbon";}', 'a:4:{i:0;s:37:"It includes only interconnected pores";i:1;s:39:"It is always larger than total porosity";i:2;s:44:"It is affected by cementation and compaction";i:3;s:59:"It is the main reference for hydrocarbon volume calculation";}', '', 'a:3:{i:0;s:41:"Hanya mencakup pori yang saling terhubung";i:1;s:40:"Dipengaruhi oleh sementasi dan pemadatan";i:2;s:50:"Menjadi acuan utama perhitungan volume hidrokarbon";}', 'a:3:{i:0;s:37:"It includes only interconnected pores";i:1;s:44:"It is affected by cementation and compaction";i:2;s:59:"It is the main reference for hydrocarbon volume calculation";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000624', 'Manakah yang merupakan keterbatasan analisis core dalam petrofisika?', 'Which of the following are limitations of core analysis in petrophysics?', 'multi', 'PFC000000001', 'Final Advanced', 'a:4:{i:0;s:33:"Kerusakan sampel saat pengambilan";i:1;s:53:"Ketidaksesuaian kondisi laboratorium dengan reservoir";i:2;s:44:"Core analysis tidak dapat mengukur porositas";i:3;s:46:"Sampel hanya mewakili sebagian kecil reservoir";}', 'a:4:{i:0;s:29:"Sample damage during recovery";i:1;s:54:"Laboratory conditions differ from reservoir conditions";i:2;s:37:"Core analysis cannot measure porosity";i:3;s:56:"The sample represents only a small part of the reservoir";}', '', 'a:3:{i:0;s:46:"Sampel hanya mewakili sebagian kecil reservoir";i:1;s:33:"Kerusakan sampel saat pengambilan";i:2;s:53:"Ketidaksesuaian kondisi laboratorium dengan reservoir";}', 'a:3:{i:0;s:56:"The sample represents only a small part of the reservoir";i:1;s:29:"Sample damage during recovery";i:2;s:54:"Laboratory conditions differ from reservoir conditions";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000625', 'Manakah ciri khas reservoir karbonat dibandingkan batupasir?', 'Which are characteristic features of carbonate reservoirs compared with sandstones?', 'multi', 'PFC000000001', 'Final Advanced', 'a:4:{i:0;s:29:"Rekahan dan vug umum dijumpai";i:1;s:42:"Selalu memiliki permeabilitas lebih tinggi";i:2;s:56:"Porositas dapat terbentuk setelah pengendapan (sekunder)";i:3;s:41:"Distribusi porositas sering tidak homogen";}', 'a:4:{i:0;s:29:"Fractures and vugs are common";i:1;s:31:"Always have higher permeability";i:2;s:46:"Porosity can form after deposition (secondary)";i:3;s:44:"Porosity distribution is often heterogeneous";}', '', 'a:3:{i:0;s:56:"Porositas dapat terbentuk setelah pengendapan (sekunder)";i:1;s:41:"Distribusi porositas sering tidak homogen";i:2;s:29:"Rekahan dan vug umum dijumpai";}', 'a:3:{i:0;s:46:"Porosity can form after deposition (secondary)";i:1;s:44:"Porosity distribution is often heterogeneous";i:2;s:29:"Fractures and vugs are common";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000626', 'Urutkan tahapan diagenesis yang menurunkan kualitas reservoir dari yang paling awal.', 'Arrange the diagenetic stages that reduce reservoir quality from the earliest.', 'drag', 'PFC000000001', 'Final Advanced', 'a:5:{i:0;s:16:"Kompaksi mekanik";i:1;s:27:"Autigenesis mineral lempung";i:2;s:9:"Sementasi";i:3;s:34:"Kompaksi kimia (pressure solution)";i:4;s:23:"Pelarutan (dissolution)";}', 'a:5:{i:0;s:21:"Mechanical compaction";i:1;s:25:"Clay mineral authigenesis";i:2;s:11:"Cementation";i:3;s:39:"Chemical compaction (pressure solution)";i:4;s:11:"Dissolution";}', '', 'a:4:{i:0;s:16:"Kompaksi mekanik";i:1;s:9:"Sementasi";i:2;s:34:"Kompaksi kimia (pressure solution)";i:3;s:23:"Pelarutan (dissolution)";}', 'a:4:{i:0;s:21:"Mechanical compaction";i:1;s:11:"Cementation";i:2;s:39:"Chemical compaction (pressure solution)";i:3;s:11:"Dissolution";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000627', 'Urutkan skala ukuran pori dari yang terkecil ke terbesar.', 'Arrange pore size scales from smallest to largest.', 'drag', 'PFC000000001', 'Final Advanced', 'a:5:{i:0;s:18:"Mikropori (< 1 um)";i:1;s:20:"Mesopori (1 - 10 um)";i:2;s:19:"Makropori (> 10 um)";i:3;s:16:"Rekahan (> 1 cm)";i:4;s:12:"Vug (> 1 mm)";}', 'a:5:{i:0;s:18:"Micropore (< 1 um)";i:1;s:20:"Mesopore (1 - 10 um)";i:2;s:19:"Macropore (> 10 um)";i:3;s:17:"Fracture (> 1 cm)";i:4;s:12:"Vug (> 1 mm)";}', '', 'a:4:{i:0;s:18:"Mikropori (< 1 um)";i:1;s:20:"Mesopori (1 - 10 um)";i:2;s:19:"Makropori (> 10 um)";i:3;s:12:"Vug (> 1 mm)";}', 'a:4:{i:0;s:18:"Micropore (< 1 um)";i:1;s:20:"Mesopore (1 - 10 um)";i:2;s:19:"Macropore (> 10 um)";i:3;s:12:"Vug (> 1 mm)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000628', 'Benarkah porositas efektif selalu lebih kecil atau sama dengan porositas total?', 'Is it true that effective porosity is always less than or equal to total porosity?', 'yesorno', 'PFC000000001', 'Final Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000629', 'Benarkah batuan dengan porositas tinggi pasti memiliki permeabilitas tinggi?', 'Is it true that a rock with high porosity must have high permeability?', 'yesorno', 'PFC000000001', 'Final Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
